  const stateHome = process.env.OMO_OWN_HOST === "1" ? process.env.OMO_OWN_STATE_HOME : undefined
  if (!stateHome) return join(directory, CONTINUATION_MARKER_DIR)
  const project = resolve(directory)
  const key = createHash("sha256").update(project).digest("hex").slice(0, 12)
  return join(stateHome, `${basename(project) || "project"}-${key}`, "run-continuation")
}

